scale_pixmap (Display ** dpy, GC gc, Pixmap source, int dwidth, int dheight)
{
    Pixmap temp, dest;
    int j, end;
    float i;
    float xscale, yscale;
    unsigned int swidth, sheight;
    Window window;
    int x, y;
    unsigned border_width_return, depth;
    XGetGeometry (*dpy, source, &window, &x, &y, &swidth, &sheight,
                  &border_width_return, &depth);

    xscale = (float) swidth / (float) dwidth;   /* Scaling factors */
    yscale = (float) sheight / (float) dheight;

    dest = XCreatePixmap (*dpy, window, dwidth, dheight, depth);
    if (!dest) {
        fprintf (stderr, "%s Could not scale image", progname);
    }
    temp = XCreatePixmap (*dpy, window, dwidth, sheight, depth);
    if (!temp) {
        fprintf (stderr, "%s Could not scale image", progname);
    }

    j = 0;
    end = dwidth * xscale;
    /* Scale width of source into temp pixmap */
    for (i = 0; i <= end; i += xscale)
        XCopyArea (*dpy, source, temp, gc, i, 0, 1, sheight, j++, 0);

    j = 0;
    end = dheight * yscale;
    /* Scale height of temp into dest pixmap */
    for (i = 0; i <= end; i += yscale)
        XCopyArea (*dpy, temp, dest, gc, 0, i, dwidth, 1, 0, j++);

    XFreePixmap (*dpy, temp);
    return (Pixmap) dest;
}"},{"rank":5,"score":21.4374,"file_path":"firmware/src/hacks/maze/maze.c","start_line":1400,"end_line":1511,"focus_line":1503,"snippet_start_line":1400,"snippet_end_line":1511,"symbol_start_line":1400,"symbol_end_line":1511,"language":"C","kind":"function","symbol_id":"gh/rodbegbie/stopwatch-screensaver:C:firmware/src/hacks/maze/maze.c:function:maze_init","symbol_name":"maze_init","qualified_name":"maze_init","signature":"static void * maze_init (Display *dpy_arg, Window window_arg)","signals":["body","symbol-usage","complete-symbol"],"snippet":"static void *
