                                    pacman_png, sizeof(pacman_png), &sw, &sh,
                                    &sprites_mask);
    if (!sprites || !sprites_mask) abort();

    srcy = 0;

    gc = XCreateGC (display, sprites_mask, 0, &gcv);

    pp->ghostMask = subpixmap (display, window, sprites_mask,
                               sw, sw, srcy, 1);
