                srcy += sw;
                if (srcy >= sh) abort();
            }
        }
    }

    /* load the scared ghost */
    /* m = 0; */
    for (i = 0; i < MAXGFLASH; i++) {
        for (j = 0; j < MAXGWAG; j++) {
            pp->s_ghostPixmap[i][j] =
