  free(pm);
}

static struct XshimPixmap *pixmap_new(int w, int h, int depth) {
  struct XshimPixmap *pm = (struct XshimPixmap *)calloc(1, sizeof(*pm));
  if (!pm) return NULL;
  pm->w = w;
  pm->h = h;
  pm->depth = depth;
  pm->stride = (w + 7) / 8;
  if (depth == 1)
